import type { HTMLAttributes } from "react";

export function Separator({ className = "", orientation = "horizontal", decorative = true, ...props }: HTMLAttributes<HTMLDivElement> & { orientation?: "horizontal" | "vertical"; decorative?: boolean }) {
  return <div role={decorative ? "none" : "separator"} aria-orientation={decorative ? undefined : orientation} className={`${orientation === "horizontal" ? "co-h-px co-w-full" : "co-h-full co-w-px"} co-shrink-0 co-bg-black/15 ${className}`.trim()} {...props} />;
}
